/*@@SAFELAB_LIB@@*/

// ---- Shared helpers (same block in every SafeLab workflow) ----
const rowsOf = (node) => $(node).all().map((i) => i.json).filter((r) => r && Object.keys(r).length);
const now = $now.setZone('Asia/Ho_Chi_Minh');
const today = now.toFormat('yyyy-MM-dd');
const nowIso = now.toFormat("yyyy-MM-dd'T'HH:mm:ssZZ"); // e.g. 2026-10-11T21:30:00+07:00
const year = now.year;
const esc = SafeLab.escapeHtml;
const text = (v) => (v === null || v === undefined ? '' : String(v).trim());
const lower = (v) => text(v).toLowerCase();
// Google Sheets treats text starting with = + - @ as a formula: prefix ' so it is stored as plain text.
const sheetRow = (row) => Object.fromEntries(Object.entries(row).map(([k, v]) =>
  [k, typeof v === 'string' && /^[=+\-@]/.test(v) ? "'" + v : v]));
const audit = (actor, action, entity, entityId, details) =>
  sheetRow({ ts: nowIso, actor: actor || 'system', action, entity, entity_id: entityId, details: text(details).slice(0, 1000) });
const link = (url, label) =>
  (text(url) ? `<a href="${esc(url)}">${esc(label)}</a>` : `${esc(label)} (link not configured in CONFIG)`);
const mail = (to, subject, body) => ({
  to: [...new Set([].concat(to).map(lower).filter(Boolean))].join(', '),
  subject: text(subject).replace(/\s+/g, ' '),
  html: `<div style="font-family:Arial,sans-serif;font-size:14px;line-height:1.5;color:#111">${body}` +
    '<p style="color:#6b7280;font-size:12px;margin-top:24px">Automated message from SafeLab (lab-safety approval system).</p></div>',
});
const cfg = SafeLab.configMap(rowsOf('Read CONFIG'));

// ---- 03 Training expiry: daily reminders + coordinator summary ----
const days = Number(cfg.EXPIRY_WARNING_DAYS) || 30;
const trainingTypes = rowsOf('Read TRAINING_TYPES');
const list = SafeLab.expiringTraining(rowsOf('Read TRAINING_RECORDS'), trainingTypes, today, days);
const typeLinks = {};
trainingTypes.forEach((t) => { typeLinks[text(t.training_code).toUpperCase()] = text(t.link); });

const when = (x) => (x.status === 'EXPIRED' ? `expired ${-x.days_left} day(s) ago` : `expires in ${x.days_left} day(s)`);
const th = 'style="text-align:left;padding:4px 8px;border:1px solid #ddd;background:#f3f4f6"';
const td = 'style="padding:4px 8px;border:1px solid #ddd"';

const emails = [];
const byPerson = {};
list.forEach((x) => { (byPerson[x.email] = byPerson[x.email] || []).push(x); });

Object.entries(byPerson).forEach(([email, items]) => {
  const expired = items.some((x) => x.status === 'EXPIRED');
  const rows = items.map((x) => `<tr><td ${td}><b>${esc(x.training_code)}</b> – ${esc(x.name)}</td>` +
    `<td ${td}>${esc(x.expires_on)}</td><td ${td}>${esc(when(x))}</td>` +
    `<td ${td}>${typeLinks[x.training_code] ? link(typeLinks[x.training_code], 'material') : ''}</td></tr>`).join('');
  emails.push(mail(email,
    `[SafeLab] Training ${expired ? 'expired' : 'expiring soon'} – ${items.map((x) => x.training_code).join(', ')}`,
    `<h2>Your lab-safety training needs renewal</h2>` +
    `<table style="border-collapse:collapse"><tr><th ${th}>Training</th><th ${th}>Valid until</th><th ${th}>Status</th><th ${th}></th></tr>${rows}</table>` +
    '<p>Expired training blocks new experiment approvals. After renewing, record it with the ' +
    `${link(cfg.FORM_F02_URL, 'Training Record form (F02)')}.</p>`));
});

if (list.length) {
  const rows = list.map((x) => `<tr><td ${td}>${esc(x.email)}</td><td ${td}>${esc(x.training_code)}</td>` +
    `<td ${td}>${esc(x.expires_on)}</td><td ${td}>${esc(x.status)} (${esc(when(x))})</td></tr>`).join('');
  emails.push(mail(cfg.SAFETY_COORDINATOR_EMAIL,
    `[SafeLab] Training expiry summary – ${list.length} record(s), ${Object.keys(byPerson).length} person(s)`,
    `<h2>Training expired or expiring within ${days} days (${esc(today)})</h2>` +
    `<table style="border-collapse:collapse"><tr><th ${th}>Person</th><th ${th}>Training</th><th ${th}>Valid until</th><th ${th}>Status</th></tr>${rows}</table>` +
    '<p>Each person has been sent their own reminder.</p>'));
}

const auditRows = [audit('system', 'TRAINING_EXPIRY_CHECK', 'TRAINING_RECORDS', '',
  `${list.length} record(s) expired/expiring within ${days} days; ${Object.keys(byPerson).length} reminder(s) sent`)];

return [{ json: { audit: auditRows, emails: emails.filter((e) => e.to) } }];
